<script module lang="ts">
/**
 * A segmented field for a length of time (`design/components/duration-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/duration-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  agentDuration,
  agentMember,
  commitDuration,
  durationDraft,
  durationKey,
  durationSegments,
  joinSlot,
  typeIntoDuration,
  watchEffect,
  type DurationUnit,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/duration-input.module.css'

export interface DurationInputMessages {
  /** What an empty count says as its value to assistive software. */
  empty: string
}

export interface DurationInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: number | null
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * Sets the digits, the unit words and each count's name.
   */
  locale?: string
  /**
   * The most seconds a commit holds; none by default.
   */
  max?: number
  /**
   * The one word the member writes itself.
   */
  messages?: DurationInputMessages
  /**
   * The fewest seconds a commit holds; `0` by default.
   */
  min?: number
  /**
   * Posts the committed value as whole seconds, such as `"604800"`.
   */
  name?: string
  onChange?: (seconds: number | null) => void
  /**
   * Keeps the counts focusable, but arrows and digits do not edit.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * Which counts show, in any order; they are drawn largest first. Days, hours and minutes by
   * default.
   */
  units?: readonly DurationUnit[]
  /**
   * Whole seconds, and `null` for the empty field. `onChange` reports committed values: a step
   * as it fires, typed digits when focus leaves the field or on Enter, each held inside `min`
   * and `max`.
   */
  value?: number | null
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  locale,
  max,
  messages = (() => ({ empty: 'Empty' }))(),
  min,
  name,
  onChange,
  readOnly = false,
  size = 'md',
  units,
  value,
}: DurationInputProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
let browserLanguage = $state(undefined as string | undefined)
// svelte-ignore state_referenced_locally
let draft = $state(
  durationDraft(value !== undefined ? value : (defaultValue ?? null), {
    units,
    min,
    max,
    locale: locale ?? browserLanguage ?? 'en-US',
  }),
)
let typed = $state('')
// svelte-ignore state_referenced_locally
let reported = $state((value !== undefined ? value : (defaultValue ?? null)) as number | null)
let field = $state<HTMLElement | null>(null)
const language = $derived(locale ?? browserLanguage ?? 'en-US')
const fieldOptions = $derived({ units, min, max, locale: language })
const editable = $derived(!disabled && !readOnly)
const segments = $derived(durationSegments(draft, fieldOptions, messages))
const posted = $derived(value !== undefined ? value : reported)
const moveSegment = $derived((from: EventTarget | null, by: number): void => {
  if (!(from instanceof HTMLElement)) return
  const all = [
    ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
  ]
  all[all.indexOf(from) + by]?.focus()
})
const commit = $derived((next: ReturnType<typeof durationDraft>): void => {
  const result = commitDuration(next, reported, fieldOptions)
  draft = result.draft
  if (result.changed) {
    reported = result.value
    onChange?.(result.value)
  }
})
const act = $derived((action: ReturnType<typeof durationKey>, from: EventTarget | null): void => {
  if (action.kind === 'move') {
    typed = ''
    moveSegment(from, action.by)
  } else if (action.kind === 'type') {
    typed = action.typed
    draft = action.draft
    if (action.advance) moveSegment(from, 1)
  } else if (action.kind === 'step') {
    typed = ''
    commit(action.draft)
  } else if (action.kind === 'commit') {
    typed = ''
    commit(draft)
  }
})
const segmentKeys = $derived(
  (event: KeyboardEvent, segment: ReturnType<typeof durationSegments>[number]): void => {
    const action = durationKey(
      draft,
      segment.unit,
      typed,
      event,
      { editable, rtl: getComputedStyle(event.currentTarget as HTMLElement).direction === 'rtl' },
      fieldOptions,
    )
    if (action.kind === 'pass') return
    event.preventDefault()
    act(action, event.currentTarget)
  },
)
const segmentInput = $derived(
  (event: Event, segment: ReturnType<typeof durationSegments>[number]): void => {
    event.preventDefault()
    if (!editable) return
    const data = (event as InputEvent).data ?? ''
    for (const key of data) {
      const next = typeIntoDuration(draft, segment.unit, typed, key, fieldOptions)
      typed = next.typed
      draft = next.draft
      if (next.advance) {
        moveSegment(event.currentTarget, 1)
        break
      }
    }
  },
)
const leave = $derived((event: FocusEvent): void => {
  const to = event.relatedTarget
  if (to instanceof Node && (event.currentTarget as HTMLElement).contains(to)) return
  typed = ''
  commit(draft)
})
const effect1 = () => {
  browserLanguage = globalThis.navigator?.language
}
watchEffect(effect1)
const effect2 = () => {
  value !== undefined && ((draft = durationDraft(value, fieldOptions)), (reported = value))
}
watchEffect(effect2, { watch: () => value, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'DurationInput',
    element: () => field,
    state: () => ({ value: posted, disabled: disabled, invalid: invalid, readonly: readOnly }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (readOnly) throw new Error('The field is read-only.')
            commit(durationDraft(agentDuration(value, fieldOptions), fieldOptions))
          })(),
      },
      clear: () =>
        (() => {
          if (readOnly) throw new Error('The field is read-only.')
          commit({})
        })(),
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={field}
    class={styles.field}
    role="group"
    {id}
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-disabled={(disabled) ? 'true' : undefined}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-readonly={(readOnly) ? '' : undefined}
    data-member="duration-input"
    onfocusout={(event) => { leave(event) }}
    ><div class={styles.segments}
      >{#each segments as segment (segment.unit)
        }<div class={styles.quantity}
          >{#if segment.wordFirst
            }<span class={styles.unit} aria-hidden="true">{segment.word}</span
          >{/if
          }<div
            class={styles.segment}
            role="spinbutton"
            id={`${uid}-${segment.unit}`}
            aria-label={segment.name}
            aria-labelledby={(ariaLabelledby) ? `${ariaLabelledby} ${uid}-${segment.unit}` : undefined}
            aria-describedby={ariaDescribedby}
            aria-valuenow={segment.value}
            aria-valuemin={segment.min}
            aria-valuemax={segment.max}
            aria-valuetext={segment.valueText}
            aria-required={(ariaRequired) ? 'true' : undefined}
            aria-readonly={(readOnly) ? 'true' : undefined}
            aria-disabled={(disabled) ? 'true' : undefined}
            aria-invalid={(invalid) ? 'true' : undefined}
            contenteditable={editable ? 'true' : undefined}
            inputmode="numeric"
            spellcheck="false"
            tabindex={(disabled ? undefined : '0') as never}
            data-segment={segment.unit}
            data-placeholder={(segment.placeholder) ? '' : undefined}
            data-disabled={(disabled) ? '' : undefined}
            onfocus={() => { typed = '' }}
            onkeydown={(event) => { segmentKeys(event, segment) }}
            onbeforeinput={(event) => { segmentInput(event, segment) }}
            >{segment.text
          }</div
          >{#if !segment.wordFirst
            }<span class={styles.unit} aria-hidden="true">{segment.word}</span
          >{/if
        }</div
      >{/each
    }</div
    >{#if name !== undefined
      }<input
        type="hidden"
        {name}
        value={posted === null ? '' : String(posted)}
        disabled={(disabled) ? true : undefined}
    />{/if
  }</div
>{/if
}{@render joined.end?.()}
